
-- Drop existing table if any
DROP TABLE IF EXISTS patients;

-- Create the patient database table
CREATE TABLE patients (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    age INTEGER,
    gender TEXT,
    condition TEXT,
    "riskLevel" TEXT,
    status TEXT,
    "lastConsultation" TEXT
);

